function validate(input) {
  const [{ Stocks = [] }] = input;
  const byStock = new Map();
  for (const [name, operation, day, price] of Stocks) {
    if (name === null || day === null) return 'Every trade needs a stock_name and an operation_day.';
    if (operation !== 'Buy' && operation !== 'Sell') return `Unknown operation ${operation}.`;
    if (price === null || price < 0) return `Trade of ${name} on day ${day} needs a non-negative price.`;
    const key = name.toLowerCase();
    if (!byStock.has(key)) byStock.set(key, []);
    byStock.get(key).push([day, operation]);
  }
  for (const [name, trades] of byStock) {
    trades.sort((a, b) => a[0] - b[0]);
    for (let i = 0; i < trades.length; i++) {
      if (i > 0 && trades[i][0] === trades[i - 1][0]) return `${name} trades twice on day ${trades[i][0]}.`;
      if (trades[i][1] !== (i % 2 === 0 ? 'Buy' : 'Sell')) return `${name} must alternate Buy and Sell, starting with Buy.`;
    }
    if (trades.length % 2 === 1) return `${name} ends with a Buy that is never sold.`;
  }
  return null;
}

