function generate(rand, size) {
  const small = size === 'small';
  const int = n => Math.floor(rand() * n);
  const names = small ? ['Leetcode', 'Corona Masks', 'Handbags', 'Tesla'] : Array.from({ length: 100 }, (_, k) => `Stock${k}`);
  const prices = [10, 500, 1000, 1010, 7000, 9000, 30000];
  const Stocks = [];
  const stockCount = small ? int(names.length + 1) : names.length;
  for (const name of names.slice(0, stockCount)) {
    // Small sets stay within 8 rows.
    const rounds = small ? Math.min(1 + int(2), (8 - Stocks.length) / 2) : 10;
    let day = 1 + int(3);
    for (let r = 0; r < rounds; r++) {
      Stocks.push([name, 'Buy', day, small ? prices[int(prices.length)] : 1 + int(50000)]);
      day += 1 + int(small ? 3 : 20);
      Stocks.push([name, 'Sell', day, small ? prices[int(prices.length)] : 1 + int(50000)]);
      day += 1 + int(small ? 3 : 20);
    }
  }
  for (let i = Stocks.length - 1; i > 0; i--) { const j = int(i + 1); [Stocks[i], Stocks[j]] = [Stocks[j], Stocks[i]]; }
  return [{ Stocks }];
}
